<div class="page-heading"><div><p class="eyebrow">BACKSTAGE / FULFILLMENT</p><h1>Orders.<br><em>Ready for the fans.</em></h1><p class="lead">Shipment updates are separate from payment. Contact an owner for refunds or payment verification.</p></div></div><?php Spirit\View::notice($error);?>
<?php if($view==='orders'):?><section class="panel"><div class="table-scroll"><table class="content-table"><thead><tr><th>Order</th><th>Environment</th><th>Total</th><th>Payment</th><th>Fulfillment</th><th>Review</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['reference'])?><small><?=e($row['buyer_email'])?></small></td><td><?=e($row['environment'])?></td><td><?=e(Spirit\Money::format((int)$row['total_cents']))?></td><td><?=e(Spirit\Orders::PAYMENT[$row['payment_state']])?></td><td><?=e($row['fulfillment_state'])?></td><td><a href="<?=e(app_url('admin/orders/view.php?id='.$row['id']))?>">Review order →</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>No orders yet.</p><?php endif;Spirit\Storefront::pager(compact('page','pages'),'admin/orders/');?></section>
<?php else:$a=$order['data']['address'];?><section class="panel"><h2><?=e($order['reference'])?></h2><p><?=e(strtoupper($order['environment']).' · '.Spirit\Orders::PAYMENT[$order['payment_state']])?></p><?php foreach($order['items'] as $item):?><div class="order-item"><strong><?=e($item['name'].' · '.$item['variant_label'])?> × <?=(int)$item['quantity']?></strong><span><?=e(Spirit\Money::format((int)$item['line_cents']))?></span></div><?php endforeach;Spirit\CheckoutPage::totals($order);?><h3>Delivery address</h3><address><?=e($a['recipient'])?><br><?=e($a['line_one'].' '.$a['line_two'])?><br><?=e($a['city'].', '.$a['region'].' '.$a['postal_code'])?></address><p><?=e($order['buyer_email'])?></p></section>
<section class="panel"><h2>Fulfillment</h2><?php if($order['payment_state']==='paid'):?><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="action" value="fulfill"><input type="hidden" name="revision" value="<?=(int)$order['revision']?>"><label class="field-stack">Next state<select name="fulfillment"><?php foreach(['processing','shipped','completed'] as $state):?><option value="<?=$state?>" <?=$state===$order['fulfillment_state']?'selected':''?>><?=ucfirst($state)?></option><?php endforeach;?></select></label><?php Spirit\StoreAdmin::field('carrier','Carrier',$order['tracking_carrier']);Spirit\StoreAdmin::field('tracking','Tracking number',$order['tracking_number']);?><button class="button" type="submit">Update fulfillment</button></form><?php else:?><p>This order cannot be fulfilled until payment has been verified. A store manager cannot change payment status.</p><?php endif;?></section><?php endif;?>
